"""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Profile text is untrusted: whoever uploads it is not whoever runs the service. Values are
therefore parsed with a restricted expression evaluator (literals plus pure arithmetic)
rather than ``eval()``, and ``plugin`` names are looked up in the fixed
``plugins.BUILTIN_PLUGINS`` registry rather than imported as arbitrary module paths, so no
profile can make the loader execute or import tenant-chosen code.
"""

from __future__ import annotations

import ast
import operator
import re

from plugins import BUILTIN_PLUGINS

__all__ = ["ConfigError", "PLUGIN_KEY", "load_config"]

PLUGIN_KEY = "plugin"

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*")

_MAX_VALUE_CHARS = 4_096
_MAX_DEPTH = 32
_MAX_INT_BITS = 4_096
_MAX_ITEMS = 10_000
_MAX_POW_EXPONENT = 1_000

_SEQUENCES = (str, bytes, list, tuple)

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
}

_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda item, items: item in items,
    ast.NotIn: lambda item, items: item not in items,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
}


class ConfigError(ValueError):
    """A profile could not be parsed, or asked for something the loader will not do."""


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).

    Values are restricted Python expressions: literals (numbers, strings, booleans, ``None``,
    lists, tuples, sets, dicts — arbitrarily nested), unary ``+``/``-``/``not``, arithmetic
    ``+ - * / // % **``, boolean ``and``/``or``, and comparisons. Names, calls, attribute
    access, subscripts, f-strings and comprehensions are rejected with ``ConfigError``, as
    are oversized values; ``plugin`` must name an entry in ``plugins.BUILTIN_PLUGINS``.
    """
    if not isinstance(text, str):
        raise ConfigError(f"profile text must be a string, got {type(text).__name__}")

    settings: dict[str, object] = {}
    plugin = None
    seen: dict[str, int] = {}

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        key, separator, value = line.partition("=")
        if not separator:
            raise ConfigError(f"line {lineno}: expected 'key = value', got {line!r}")

        key = key.strip()
        if not _KEY_RE.fullmatch(key):
            raise ConfigError(f"line {lineno}: invalid key {key!r}")
        if key in seen:
            raise ConfigError(f"line {lineno}: duplicate key {key!r} (already set on line {seen[key]})")
        seen[key] = lineno

        value = value.strip()
        if not value:
            raise ConfigError(f"line {lineno}: key {key!r} has no value")

        parsed = _parse_value(value, lineno)
        if key == PLUGIN_KEY:
            plugin = _resolve_plugin(parsed, lineno)
        else:
            settings[key] = parsed

    return {"settings": settings, "plugin": plugin}


def _resolve_plugin(name: object, lineno: int):
    """Instantiate a built-in transform by its registry name."""
    if not isinstance(name, str):
        raise ConfigError(
            f"line {lineno}: {PLUGIN_KEY!r} must be a plugin name string, got {type(name).__name__}"
        )
    try:
        plugin_class = BUILTIN_PLUGINS[name]
    except KeyError:
        available = ", ".join(sorted(BUILTIN_PLUGINS)) or "(none)"
        raise ConfigError(
            f"line {lineno}: unknown plugin {name!r}; available plugins: {available}"
        ) from None
    return plugin_class()


def _parse_value(value: str, lineno: int):
    """Parse one profile value into a Python object without running tenant code."""
    if len(value) > _MAX_VALUE_CHARS:
        raise ConfigError(f"line {lineno}: value exceeds {_MAX_VALUE_CHARS} characters")

    try:
        tree = ast.parse(value, mode="eval")
    except (SyntaxError, ValueError) as exc:
        raise ConfigError(f"line {lineno}: value {value!r} is not a valid expression: {exc}") from None

    try:
        return _eval_node(tree.body, lineno)
    except RecursionError as exc:  # pragma: no cover - depth guard normally fires first
        raise ConfigError(f"line {lineno}: value {value!r} is nested too deeply") from exc
    except MemoryError as exc:  # pragma: no cover - size guards normally fire first
        raise ConfigError(f"line {lineno}: value {value!r} is too large") from exc


def _eval_node(node: ast.AST, lineno: int, depth: int = 0):
    if depth > _MAX_DEPTH:
        raise ConfigError(f"line {lineno}: value nests deeper than {_MAX_DEPTH} levels")
    child = depth + 1

    if isinstance(node, ast.Constant):
        return _check_size(node.value, lineno)

    if isinstance(node, (ast.List, ast.Tuple)):
        items = [_eval_node(element, lineno, child) for element in node.elts]
        return _check_size(items if isinstance(node, ast.List) else tuple(items), lineno)

    if isinstance(node, ast.Set):
        return _check_size({_eval_node(element, lineno, child) for element in node.elts}, lineno)

    if isinstance(node, ast.Dict):
        result = {}
        for key_node, value_node in zip(node.keys, node.values):
            if key_node is None:
                raise _reject(node, lineno)
            result[_eval_node(key_node, lineno, child)] = _eval_node(value_node, lineno, child)
        return _check_size(result, lineno)

    if isinstance(node, ast.UnaryOp):
        operation = _UNARY_OPS.get(type(node.op))
        if operation is None:
            raise _reject(node, lineno)
        return _check_size(operation(_eval_node(node.operand, lineno, child)), lineno)

    if isinstance(node, ast.BinOp):
        operation = _BIN_OPS.get(type(node.op))
        if operation is None:
            raise _reject(node, lineno)
        left = _eval_node(node.left, lineno, child)
        right = _eval_node(node.right, lineno, child)
        if isinstance(node.op, ast.Mult):
            _check_repeat(left, right, lineno)
        if isinstance(node.op, ast.Pow):
            _check_exponent(right, lineno)
        try:
            return _check_size(operation(left, right), lineno)
        except ZeroDivisionError as exc:
            raise ConfigError(f"line {lineno}: division by zero in profile value") from exc
        except OverflowError as exc:
            raise ConfigError(f"line {lineno}: numeric overflow in profile value") from exc

    if isinstance(node, ast.BoolOp):
        values = [_eval_node(value, lineno, child) for value in node.values]
        result = values[0]
        for value in values[1:]:
            result = value if (result if isinstance(node.op, ast.Or) else not result) else result
        return bool(result) if isinstance(node.op, (ast.And, ast.Or)) else result

    if isinstance(node, ast.Compare):
        left = _eval_node(node.left, lineno, child)
        for operation, comparator in zip(node.ops, node.comparators):
            compare = _CMP_OPS.get(type(operation))
            if compare is None:
                raise _reject(node, lineno)
            right = _eval_node(comparator, lineno, child)
            if not compare(left, right):
                return False
            left = right
        return True

    raise _reject(node, lineno)


def _reject(node: ast.AST, lineno: int) -> ConfigError:
    kind = type(node).__name__
    return ConfigError(f"line {lineno}: {kind} expressions are not allowed in profile values")


def _check_size(value: object, lineno: int):
    """Bound numbers and sequences so a small profile cannot exhaust CPU or memory."""
    if isinstance(value, int) and not isinstance(value, bool) and value.bit_length() > _MAX_INT_BITS:
        raise ConfigError(f"line {lineno}: numeric value exceeds {_MAX_INT_BITS} bits")
    if isinstance(value, _SEQUENCES) and len(value) > _MAX_ITEMS:
        raise ConfigError(f"line {lineno}: sequence value exceeds {_MAX_ITEMS} items")
    return value


def _check_repeat(left: object, right: object, lineno: int) -> None:
    for sequence, count in ((left, right), (right, left)):
        if isinstance(sequence, _SEQUENCES) and isinstance(count, int) and not isinstance(count, bool):
            if count > 0 and len(sequence) * count > _MAX_ITEMS:
                raise ConfigError(f"line {lineno}: repetition exceeds {_MAX_ITEMS} items")


def _check_exponent(exponent: object, lineno: int) -> None:
    if isinstance(exponent, (int, float)) and not isinstance(exponent, bool):
        if abs(exponent) > _MAX_POW_EXPONENT:
            raise ConfigError(f"line {lineno}: exponent exceeds {_MAX_POW_EXPONENT}")
